const body = $json.body ?? $json;
const conversation = body.conversation ?? {};
const attributes = conversation.custom_attributes ?? {};
const event = body.event;
const messageType = body.message_type;
const messageId = body.id;
const inboxId = conversation.inbox_id ?? conversation.inbox?.id;
const content = String(body.content ?? '').trim();
const stage = attributes.cbn_fgts_bot_stage;
const lastMessageId = attributes.cbn_fgts_last_message_id;

const base = {
  action: 'ignore',
  accountId: 1,
  conversationId: conversation.id,
  inboxId,
  messageId,
  attributes,
  handoff: false,
};

if (event !== 'message_created' || messageType !== 'incoming' || String(inboxId) !== '2' || !messageId || String(messageId) === String(lastMessageId ?? '')) {
  return [];
}

const normalizeText = (value) => String(value ?? '')
  .normalize('NFD')
  .replace(/\p{Diacritic}/gu, '')
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .trim();

const normalized = normalizeText(content);
const isFgtsLead = normalized.includes('quero simular meu fgts') || normalized.includes('quero simular minha antecipacao do fgts');

if (!stage && isFgtsLead) {
  return [{ json: {
    ...base,
    action: 'reply',
    message: 'Olá! 👋 Sou a assistente virtual da CBN Crédito.\n\nPara verificarmos as opções disponíveis para você, envie seu CPF com os 11 números, por favor.',
    nextAttributes: {
      ...attributes,
      cbn_fgts_bot_stage: 'awaiting_cpf',
      cbn_fgts_last_message_id: String(messageId),
    },
  } }];
}

if (!stage) return [{ json: { ...base, action: 'handoff', handoff: true } }];
if (stage !== 'awaiting_cpf') return [{ json: { ...base, action: 'handoff', handoff: true } }];

const normalizeCpf = (value) => {
  const raw = String(value ?? '').trim();
  if (!raw || /[a-z]/i.test(raw) || /[^\d.\-\s]/.test(raw)) return null;
  return raw.replace(/\D/g, '');
};
const cpf = normalizeCpf(content);
const calculateDigit = (value, length) => {
  let sum = 0;
  for (let index = 0; index < length; index += 1) sum += Number(value[index]) * (length + 1 - index);
  const remainder = (sum * 10) % 11;
  return remainder === 10 ? 0 : remainder;
};
const validCpf = Boolean(cpf) && cpf.length === 11 && !/^(\d)\1{10}$/.test(cpf) && calculateDigit(cpf, 9) === Number(cpf[9]) && calculateDigit(cpf, 10) === Number(cpf[10]);

if (!validCpf) {
  return [{ json: {
    ...base,
    action: 'reply',
    message: 'CPF inválido, pode enviar novamente?',
    nextAttributes: {
      ...attributes,
      cbn_fgts_bot_stage: 'awaiting_cpf',
      cbn_fgts_last_message_id: String(messageId),
    },
  } }];
}

return [{ json: {
  ...base,
  action: 'reply',
  message: 'CPF recebido ✅\n\nAgora preciso que você autorize a consulta do seu FGTS.\n\nAbra o aplicativo FGTS ou a Carteira de Trabalho Digital e autorize a instituição:\n\nGIRO SOCIEDADE DE CRÉDITO\n\nQuando concluir, responda PRONTO.',
  nextAttributes: {
    ...attributes,
    cbn_fgts_bot_stage: 'handed_off',
    cbn_fgts_last_message_id: String(messageId),
  },
  handoff: true,
} }];
